insert into public.content_lessons (id, slug, title, category_id, kind, summary, reading_minutes, body, key_takeaways, official_sources, last_reviewed, needs_verification, related_video_id, related_quiz_id, xp, sort_order, featured, published) values
  ('lesson-module-5', 'decoding-your-pay-stub', 'Module 5: Decoding Your Pay Stub', 'your-paycheque', 'lesson', 'Your paycheque is smaller than hours times wage. Here is exactly where the money went.', 4, '[{"type":"heading","text":"Gross vs net"},{"type":"paragraph","text":"Gross pay is what you earned. Net pay is what lands in your account after deductions."},{"type":"heading","text":"The big three deductions"},{"type":"paragraph","text":"Income tax, CPP pension contributions and EI premiums commonly reduce pay. These lessons use CPP and non-Quebec EI rules; Quebec has QPP and different EI premiums."},{"type":"heading","text":"Age matters"},{"type":"paragraph","text":"CPP deductions generally begin the month after you turn 18 on pensionable pay, subject to the basic exemption. EI has no minimum age and applies to insurable earnings from the first dollar, up to the annual maximum."},{"type":"heading","text":"The TD1 form"},{"type":"paragraph","text":"You fill it out when you start a job. It tells your employer how much tax to hold back."},{"type":"table","headers":["2026 payroll item","Reference value (outside Quebec)"],"rows":[["CPP employee rate","5.95% on pensionable earnings above the $3,500 annual exemption up to $74,600; CPP2 is separate"],["CPP2","4% on the pensionable earnings band above $74,600 up to $85,000"],["EI employee rate","1.63% on insurable earnings up to $68,900"]]},{"type":"example","title":"Ava''s shrinking paycheque","text":"Ava turned 18 in March. Her April paycheque was smaller even though she worked the same hours. What changed?\n\nAssuming pensionable earnings exceed the applicable exemption, CPP deductions started in April, the month after Ava turned 18. CPP contributions help build pension entitlement."}]'::jsonb, '["Gross vs net. Gross pay is what you earned. Net pay is what lands in your account after deductions.","The big three deductions. Income tax, CPP pension contributions and EI premiums commonly reduce pay. These lessons use CPP and non-Quebec EI rules; Quebec has QPP and different EI premiums.","Age matters. CPP deductions generally begin the month after you turn 18 on pensionable pay, subject to the basic exemption. EI has no minimum age and applies to insurable earnings from the first dollar, up to the annual maximum.","The TD1 form. You fill it out when you start a job. It tells your employer how much tax to hold back."]'::jsonb, '[{"label":"CRA guidance","url":"https://www.canada.ca/en/revenue-agency/services/forms-publications/payroll/t4032-payroll-deductions-tables/t4032bc-july/t4032bc-july-general-information.html"}]'::jsonb, '2026-10-18', true, null, null, 10, 25, false, true),
  ('lesson-module-6', 'how-tax-brackets-really-work', 'Module 6: How Tax Brackets Really Work', 'tax-basics', 'lesson', 'A higher tax bracket only affects the next slice of income. Learn what a raise really changes.', 4, '[{"type":"heading","text":"Brackets are buckets"},{"type":"paragraph","text":"Each rate only applies to the dollars inside that bucket, not your whole income."},{"type":"heading","text":"Marginal rate"},{"type":"paragraph","text":"The rate on your next dollar of taxable income. In 2026 the first federal bracket is 14% up to $58,523; the next is 20.5% up to $117,045. Higher brackets also exist."},{"type":"heading","text":"Average rate"},{"type":"paragraph","text":"Total income tax divided by income. In a simple progressive-bracket example it is below the marginal rate when some income falls into lower brackets. The two can be equal if all taxable dollars face one rate before credits."},{"type":"heading","text":"Two layers"},{"type":"paragraph","text":"You pay federal tax plus provincial tax (BC has its own brackets). Lessons here use federal numbers only."},{"type":"table","headers":["2026 federal item","Reference value"],"rows":[["Maximum basic personal amount","$16,452; reduced at higher incomes and subject to special rules"],["First bracket","14% up to $58,523 of taxable income"],["Second bracket","20.5% above $58,523 up to $117,045"]]},{"type":"example","title":"Noah''s \"bad\" raise","text":"Noah earns $58,000 and is offered a raise to $60,000. A coworker warns him it will bump him into a higher bracket and he will lose money. Should he turn it down?\n\nA higher bracket alone does not make the whole income face the higher rate. In this simplified taxable-income example, $523 is taxed at 14% and $1,477 at 20.5%: $375.61 extra federal tax, leaving $1,624.39 of the raise before provincial tax, CPP, EI and any benefit changes."}]'::jsonb, '["Brackets are buckets. Each rate only applies to the dollars inside that bucket, not your whole income.","Marginal rate. The rate on your next dollar of taxable income. In 2026 the first federal bracket is 14% up to $58,523; the next is 20.5% up to $117,045. Higher brackets also exist.","Average rate. Total income tax divided by income. In a simple progressive-bracket example it is below the marginal rate when some income falls into lower brackets. The two can be equal if all taxable dollars face one rate before credits.","Two layers. You pay federal tax plus provincial tax (BC has its own brackets). Lessons here use federal numbers only."]'::jsonb, '[{"label":"CRA guidance 1","url":"https://www.canada.ca/en/revenue-agency/services/tax/individuals/tax-rates-brackets/current-year.html"},{"label":"CRA guidance 2","url":"https://www.canada.ca/en/revenue-agency/services/tax/businesses/topics/payroll/payroll-deductions-contributions/income-tax/reducing-remuneration-subject-income-tax.html"}]'::jsonb, '2026-10-18', true, null, null, 10, 26, false, true),
  ('lesson-module-7', 'side-hustles-and-gig-income', 'Module 7: Side Hustles and Gig Income', 'employment-and-gig-income', 'lesson', 'Tutoring, reselling, babysitting, content creation. If you earn it, the CRA cares about it.', 4, '[{"type":"heading","text":"Cash still counts"},{"type":"paragraph","text":"Business earnings from tutoring, lawn mowing and online work must be reported even without a T4. A transfer between your own accounts or a personal gift is not automatically business income."},{"type":"heading","text":"Profit, not sales"},{"type":"paragraph","text":"Report gross business revenue and eligible expenses; net profit is the business income used in your tax calculation. Personal expenses are not deductible."},{"type":"heading","text":"Keep receipts"},{"type":"paragraph","text":"Track revenue, eligible expenses and business use of a vehicle. Generally keep tax records for six years from the end of the last tax year they relate to; some records must be kept longer."},{"type":"heading","text":"The $30,000 test"},{"type":"paragraph","text":"For most businesses, mandatory GST/HST registration depends on worldwide taxable supplies, including associates, exceeding $30,000 in one calendar quarter or over four consecutive quarters. Timing differs between these tests. Exempt tutoring and special rules such as commercial ride-sharing need separate treatment."},{"type":"example","title":"Ethan''s tutoring business","text":"Ethan, 19, earned $6,000 tutoring math by e-transfer and spent $400 on textbooks and ads. He also has a T4 from a summer job. Does he need to report the tutoring?\n\nYes. Report $6,000 of gross tutoring revenue and $400 of eligible expenses, for $5,600 net business income, alongside the T4. These amounts alone do not exceed the usual GST/HST small-supplier threshold. Some curriculum-based tutoring is exempt; do not assume all tutoring is taxable."}]'::jsonb, '["Cash still counts. Business earnings from tutoring, lawn mowing and online work must be reported even without a T4. A transfer between your own accounts or a personal gift is not automatically business income.","Profit, not sales. Report gross business revenue and eligible expenses; net profit is the business income used in your tax calculation. Personal expenses are not deductible.","Keep receipts. Track revenue, eligible expenses and business use of a vehicle. Generally keep tax records for six years from the end of the last tax year they relate to; some records must be kept longer.","The $30,000 test. For most businesses, mandatory GST/HST registration depends on worldwide taxable supplies, including associates, exceeding $30,000 in one calendar quarter or over four consecutive quarters. Timing differs between these tests. Exempt tutoring and special rules such as commercial ride-sharing need separate treatment."]'::jsonb, '[{"label":"CRA guidance 1","url":"https://www.canada.ca/en/revenue-agency/services/tax/businesses/topics/gst-hst-businesses/when-register-charge.html"},{"label":"CRA guidance 2","url":"https://www.canada.ca/en/revenue-agency/services/forms-publications/publications/t4002.html"}]'::jsonb, '2026-10-18', true, null, null, 10, 27, false, true),
  ('lesson-module-8', 'free-money-from-filing', 'Module 8: Free Money from Filing', 'credits-and-benefits', 'lesson', 'The government cannot send you money it does not know you are owed. Filing is how you tell it.', 4, '[{"type":"heading","text":"Refunds of overpaid deductions"},{"type":"paragraph","text":"If your employer withheld more tax, CPP or EI than you owed, filing gets it back."},{"type":"heading","text":"Small earners get EI back"},{"type":"paragraph","text":"If your insurable earnings for the year were $2,000 or less, your EI premiums are refunded."},{"type":"heading","text":"Quarterly benefits"},{"type":"paragraph","text":"The Canada Groceries and Essentials Benefit (CGEB) replaced the GST/HST credit in July 2026. It is tax-free and income-tested. Generally eligibility starts at 19, with exceptions for a spouse or common-law partner or a parent living with their child. File the year before you turn 19."},{"type":"heading","text":"Canada Workers Benefit"},{"type":"paragraph","text":"A refundable credit for eligible lower-income workers. Age, residency and family rules apply. Full-time students for more than 13 weeks generally do not qualify unless they have an eligible dependant."},{"type":"example","title":"Sam skips filing","text":"Sam, 18, earned $9,000 at a grocery store and $450 in income tax was withheld. He figures he earned too little to bother filing. What is he missing?\n\nAssuming Sam is a full-year Canadian resident with only that income and no offsets, he would generally recover the $450 withheld income tax. Filing also lets the CRA assess CGEB eligibility as he approaches 19 and establishes earned income for future RRSP room; benefit payment is not guaranteed."}]'::jsonb, '["Refunds of overpaid deductions. If your employer withheld more tax, CPP or EI than you owed, filing gets it back.","Small earners get EI back. If your insurable earnings for the year were $2,000 or less, your EI premiums are refunded.","Quarterly benefits. The Canada Groceries and Essentials Benefit (CGEB) replaced the GST/HST credit in July 2026. It is tax-free and income-tested. Generally eligibility starts at 19, with exceptions for a spouse or common-law partner or a parent living with their child. File the year before you turn 19.","Canada Workers Benefit. A refundable credit for eligible lower-income workers. Age, residency and family rules apply. Full-time students for more than 13 weeks generally do not qualify unless they have an eligible dependant."]'::jsonb, '[{"label":"CRA guidance 1","url":"https://www.canada.ca/en/revenue-agency/services/tax/individuals/educational-programs/accessing-benefits-credits.html"},{"label":"CRA guidance 2","url":"https://www.canada.ca/en/revenue-agency/services/child-family-benefits/canada-groceries-essentials-benefit.html"}]'::jsonb, '2026-10-18', true, null, null, 10, 28, false, true),
  ('lesson-module-9', 'fhsa-rrsp-and-big-goals', 'Module 9: FHSA, RRSP and Big Goals', 'tfsa-and-rrsp', 'lesson', 'Saving for a first home or retirement at 18 sounds early. That is exactly why it works.', 4, '[{"type":"heading","text":"FHSA"},{"type":"paragraph","text":"Eligible Canadian-resident first-time home buyers can generally open one from 18, but must be 19 where local contract law requires it, including BC. Contributions can be deductible and qualifying home withdrawals tax-free."},{"type":"heading","text":"FHSA limits"},{"type":"paragraph","text":"Initial participation room is $8,000 and the lifetime limit is $40,000. Room starts when the first account opens; unused carryforward is capped at $8,000. Opening also starts the maximum participation period, generally 15 years, with other closing triggers."},{"type":"heading","text":"RRSP room"},{"type":"paragraph","text":"New room is generally based on 18% of the previous year''s earned income, subject to the annual dollar limit and pension adjustments. Check your CRA deduction limit before contributing."},{"type":"heading","text":"Deduct later"},{"type":"paragraph","text":"You can contribute to an RRSP now and save the deduction for a future year when your tax rate is higher."},{"type":"table","headers":["2026 account limit","Amount"],"rows":[["TFSA annual dollar limit","$7,000; your available room also depends on eligibility, contributions and withdrawals"],["FHSA annual participation room","$8,000 when the first FHSA opens; limited unused room can carry forward"],["FHSA lifetime limit","$40,000"]]},{"type":"example","title":"Chloe''s first $2,000","text":"Chloe, 19, has $2,000 saved and wants to buy a condo in about 8 years. She makes $14,000 a year, so she pays almost no tax right now. FHSA or TFSA first?\n\nOne option, if Chloe meets FHSA eligibility rules, is to open one to start participation room and defer the deduction to a later year. Opening also starts the maximum participation period, generally 15 years. A TFSA provides flexible withdrawals. Compare her emergency needs and home-buying plans before choosing."}]'::jsonb, '["FHSA. Eligible Canadian-resident first-time home buyers can generally open one from 18, but must be 19 where local contract law requires it, including BC. Contributions can be deductible and qualifying home withdrawals tax-free.","FHSA limits. Initial participation room is $8,000 and the lifetime limit is $40,000. Room starts when the first account opens; unused carryforward is capped at $8,000. Opening also starts the maximum participation period, generally 15 years, with other closing triggers.","RRSP room. New room is generally based on 18% of the previous year''s earned income, subject to the annual dollar limit and pension adjustments. Check your CRA deduction limit before contributing.","Deduct later. You can contribute to an RRSP now and save the deduction for a future year when your tax rate is higher."]'::jsonb, '[{"label":"CRA guidance 1","url":"https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/first-home-savings-account/opening-your-fhsas.html"},{"label":"CRA guidance 2","url":"https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/first-home-savings-account/contributing-your-fhsa.html"},{"label":"CRA guidance 3","url":"https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/tax-free-savings-account/contributions.html"}]'::jsonb, '2026-10-18', true, null, null, 10, 29, false, true),
  ('lesson-module-10', 'moving-out-for-school', 'Module 10: Moving Out for School', 'slips-and-documents', 'lesson', 'University comes with new tax slips, new credits and a few traps. Here is your first-year survival kit.', 4, '[{"type":"heading","text":"The T2202"},{"type":"paragraph","text":"Your school issues it each year. It shows the eligible tuition you can claim."},{"type":"heading","text":"Use it, transfer it or carry it forward"},{"type":"paragraph","text":"First claim the tuition amount required to reduce your own federal tax. Up to $5,000 of current-year tuition, minus the amount you need, may be transferred to an eligible relative. This is a tuition amount, not $5,000 cash. Prior-year carryforwards cannot be transferred."},{"type":"heading","text":"Scholarships"},{"type":"paragraph","text":"A scholarship connected to a qualifying full-time program may be fully exempt. Enter the T4A accurately in tax software and apply the exemption; only the taxable portion belongs on line 13010, not an automatically taxable full amount."},{"type":"heading","text":"RESP money"},{"type":"paragraph","text":"Growth and grants paid out to you count as your income, though your low student income often means little or no tax."},{"type":"example","title":"Lucas and his tuition credits","text":"Lucas paid $7,000 in tuition and earned only $4,000 from a part-time job, so he owes no tax. His mom asks if she can use his credits. What are his options?\n\nAssuming the $7,000 is eligible current-year tuition and none is needed against his own federal tax, Lucas can designate up to $5,000 to an eligible parent and carry the other $2,000 forward, or carry all $7,000 forward. The transfer is a tuition amount, not a $5,000 refund. He must file Schedule 11."}]'::jsonb, '["The T2202. Your school issues it each year. It shows the eligible tuition you can claim.","Use it, transfer it or carry it forward. First claim the tuition amount required to reduce your own federal tax. Up to $5,000 of current-year tuition, minus the amount you need, may be transferred to an eligible relative. This is a tuition amount, not $5,000 cash. Prior-year carryforwards cannot be transferred.","Scholarships. A scholarship connected to a qualifying full-time program may be fully exempt. Enter the T4A accurately in tax software and apply the exemption; only the taxable portion belongs on line 13010, not an automatically taxable full amount.","RESP money. Growth and grants paid out to you count as your income, though your low student income often means little or no tax."]'::jsonb, '[{"label":"CRA guidance 1","url":"https://www.canada.ca/en/revenue-agency/services/forms-publications/publications/p105/p105-students-income-tax.html"},{"label":"CRA guidance 2","url":"https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/about-your-tax-return/tax-return/completing-a-tax-return/deductions-credits-expenses/line-21900-moving-expenses.html"}]'::jsonb, '2026-10-18', true, null, null, 10, 30, false, true),
  ('lesson-module-11', 'cra-scams-deadlines-and-mistakes', 'Module 11: CRA Scams, Deadlines and Mistakes', 'deadlines-and-penalties', 'lesson', 'The real CRA will never text you a gift card demand. Learn to spot the fakes and dodge the fees.', 4, '[{"type":"heading","text":"Scam red flags"},{"type":"paragraph","text":"The CRA does not demand gift cards or cryptocurrency and does not threaten immediate arrest to force payment. Verify suspicious contact independently through official CRA contact details."},{"type":"heading","text":"Deadlines"},{"type":"paragraph","text":"The usual individual filing and payment deadline is April 30. Most self-employed individuals and their spouses or common-law partners have until June 15 to file, but payment is still normally due April 30. Weekend and public-holiday rules can shift dates; check the relevant filing year."},{"type":"heading","text":"Late filing"},{"type":"paragraph","text":"The standard penalty when a balance is owing is 5% of the unpaid balance plus 1% per full month late, up to 12 months. Repeat late filing can have higher penalties, and late-payment interest is separate."},{"type":"heading","text":"Notice of Assessment"},{"type":"paragraph","text":"Read the CRA summary after you file, including any changes and your available RRSP deduction limit. Generally keep supporting tax records for six years; some must be retained longer."},{"type":"example","title":"Mia''s suspicious text","text":"Mia gets a text saying she has a $437 CRA refund waiting, with a link to \"claim it now\" by entering her SIN and banking info. What should she do?\n\nDo not click or enter personal information. Visit CRA My Account through an independently verified official address and report the suspicious message to the Canadian Anti-Fraud Centre."}]'::jsonb, '["Scam red flags. The CRA does not demand gift cards or cryptocurrency and does not threaten immediate arrest to force payment. Verify suspicious contact independently through official CRA contact details.","Deadlines. The usual individual filing and payment deadline is April 30. Most self-employed individuals and their spouses or common-law partners have until June 15 to file, but payment is still normally due April 30. Weekend and public-holiday rules can shift dates; check the relevant filing year.","Late filing. The standard penalty when a balance is owing is 5% of the unpaid balance plus 1% per full month late, up to 12 months. Repeat late filing can have higher penalties, and late-payment interest is separate.","Notice of Assessment. Read the CRA summary after you file, including any changes and your available RRSP deduction limit. Generally keep supporting tax records for six years; some must be retained longer."]'::jsonb, '[{"label":"CRA guidance 1","url":"https://www.canada.ca/en/revenue-agency/campaigns/fraud-scams.html"},{"label":"CRA guidance 2","url":"https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/about-your-tax-return/interest-penalties/late-filing-penalty.html"},{"label":"CRA guidance 3","url":"https://www.canada.ca/en/services/taxes/income-tax/personal-income-tax/after-you-file/change-return.html"}]'::jsonb, '2026-10-18', true, null, null, 10, 31, false, true),
  ('lesson-credits-benefits', 'credits-and-benefits', 'Credits and benefits: money that comes back', 'credits-and-benefits', 'lesson', 'Filing is not only about paying. It is how the CRA works out payments owed to you.', 3, '[{"type":"paragraph","text":"Here is a part people wish they learned sooner. Filing your taxes is not only about paying. It can also unlock payments that come to you, even if you earned very little."},{"type":"heading","text":"The CGEB (formerly GST/HST credit)"},{"type":"paragraph","text":"One common one is the CGEB (formerly GST/HST credit). It is a tax free payment that helps lower income people with the sales tax they pay on everyday things. A few points to know:"},{"type":"bullets","items":["You usually need to be 19 or older to get it on your own.","It is tax free, which means you do not pay any tax on it.","You do not fill out a separate application. The CRA works out if you qualify automatically when you file."]},{"type":"warning","title":"Amounts and ages change","text":"Eligibility rules and payment amounts are updated regularly. Confirm the current rules on canada.ca before counting on a payment."},{"type":"heading","text":"Why filing matters so much"},{"type":"paragraph","text":"Payments like the CGEB (formerly GST/HST credit) and the Canada Child Benefit are calculated using the information on your tax return. No return means the CRA cannot calculate them, so the payments can stop. The rule is simple: file every single year, even a year when you had no income, so your payments keep coming."}]'::jsonb, '["The CGEB (formerly GST/HST credit) is a tax free payment for lower income people.","You generally need to be 19 or older to get it on your own.","You get it just by filing. There is no separate application.","Benefit payments are based on your return, so file every year."]'::jsonb, '[{"label":"CGEB (formerly GST/HST credit) — CRA","url":"https://www.canada.ca/en/revenue-agency/services/child-family-benefits/goods-services-tax-harmonized-sales-tax-gst-hst-credit.html"},{"label":"Canada Revenue Agency","url":"https://www.canada.ca/en/revenue-agency.html"}]'::jsonb, '2026-09-20', true, null, null, 15, 1, false, true),
  ('lesson-glossary', 'tax-glossary', 'Tax glossary: every term in one place', 'tax-glossary', 'lesson', 'Quick meanings of the words used across TaxIntuitive.', 3, '[{"type":"paragraph","text":"Quick meanings of the words used in these lessons. Tap any term in the Glossary tab to see it on its own."},{"type":"terms","items":["CRA","SIN","Gross pay","Net pay","CPP","EI","NETFILE","Refund","CGEB (formerly GST/HST credit)","TFSA","RRSP","T4","T4A","T5","T2202","TD1"]}]'::jsonb, '["Knowing the vocabulary makes every other lesson easier."]'::jsonb, '[{"label":"Canada Revenue Agency","url":"https://www.canada.ca/en/revenue-agency.html"}]'::jsonb, '2026-09-20', false, null, null, 10, 1, false, true),
  ('guide-deductions-vs-credits', 'understanding-deductions-and-credits', 'Understanding Deductions & Credits', 'credits-and-benefits', 'guide', 'Two different ways your tax bill gets smaller, and why the difference matters.', 3, '[{"type":"paragraph","text":"People use \"deduction\" and \"credit\" as if they mean the same thing. They do not, and the difference changes how much you actually save."},{"type":"heading","text":"A deduction lowers the income you are taxed on"},{"type":"paragraph","text":"A deduction comes off your income before tax is calculated. An RRSP contribution is the classic example: put money in, and there is less income left to tax."},{"type":"heading","text":"A credit lowers the tax itself"},{"type":"paragraph","text":"A credit is applied after your tax is calculated, reducing the tax amount directly. Tuition from a T2202 works this way."},{"type":"table","headers":["","Deduction","Credit"],"rows":[["Applies to","Your income","Your tax"],["Example","RRSP contribution","Tuition (T2202)"],["Applied","Before tax is worked out","After tax is worked out"]]},{"type":"tip","title":"Refundable vs non-refundable","text":"Some credits can only reduce tax to zero. Others, like the CGEB (formerly GST/HST credit), can pay you even when you owe nothing — which is why filing matters at low incomes."},{"type":"warning","title":"What you can claim changes","text":"Which deductions and credits you qualify for depends on current rules and your situation. Verify on canada.ca or ask a professional."}]'::jsonb, '["A deduction reduces the income you are taxed on.","A credit reduces the tax you owe.","RRSP contributions are a deduction; tuition is a credit.","Some credits can pay you even when you owe no tax."]'::jsonb, '[{"label":"Personal income tax — Canada.ca","url":"https://www.canada.ca/en/services/taxes/income-tax/personal-income-tax.html"},{"label":"Canada Revenue Agency","url":"https://www.canada.ca/en/revenue-agency.html"}]'::jsonb, '2026-09-20', true, null, null, 15, 3, true, true),
  ('guide-do-i-need-to-file', 'do-i-need-to-file-a-quick-check', 'Do I Need to File? A Quick Check', 'tax-basics', 'guide', 'A short list of reasons to file — including the ones that pay you.', 2, '[{"type":"paragraph","text":"Some people must file. Many more should file because it pays them. Read both lists."},{"type":"heading","text":"Reasons you may have to file"},{"type":"bullets","items":["You owe tax for the year.","You had self-employment or gig income.","The CRA sent you a request to file."]},{"type":"heading","text":"Reasons you should file anyway"},{"type":"bullets","items":["Tax was taken off your pay and you may be owed a refund.","Filing is how benefit and credit payments get calculated — no return, no payments.","It starts your RRSP contribution room for the future.","Tuition on a T2202 can be carried forward to a year when it helps more."]},{"type":"tip","title":"The short version","text":"If you earned anything at all, file. At low incomes, filing is usually how you get money rather than owe it."},{"type":"warning","title":"Confirm your own situation","text":"Whether you are required to file depends on current rules and your circumstances. Check canada.ca or a professional if you are unsure."}]'::jsonb, '["You must file if you owe tax, had gig income, or the CRA asks.","You should file to claim a refund and keep benefits flowing.","Filing builds RRSP room and banks tuition credits.","When in doubt at a low income, filing usually pays you."]'::jsonb, '[{"label":"Personal income tax — Canada.ca","url":"https://www.canada.ca/en/services/taxes/income-tax/personal-income-tax.html"},{"label":"CGEB (formerly GST/HST credit) — CRA","url":"https://www.canada.ca/en/revenue-agency/services/child-family-benefits/goods-services-tax-harmonized-sales-tax-gst-hst-credit.html"}]'::jsonb, '2026-09-20', true, null, null, 15, 4, true, true),
  ('guide-tax-brackets', 'how-tax-brackets-actually-work', 'How Tax Brackets Actually Work', 'tax-basics', 'guide', 'The biggest tax myth, busted: a raise does not tax every dollar you earn at a higher rate.', 3, '[{"type":"paragraph","text":"Here is the myth: \"I got a raise and moved into a higher tax bracket, so now I take home less.\" That is not how it works."},{"type":"heading","text":"Brackets apply to slices, not the whole pie"},{"type":"paragraph","text":"Canada uses graduated tax rates. Your income is divided into slices, and each slice is taxed at its own rate. Moving into a higher bracket only changes the rate on the dollars inside that higher slice — not on the dollars below it."},{"type":"example","title":"The idea in plain numbers","text":"Imagine the first slice of income is taxed at a low rate and the next slice at a higher one. If you earn one dollar more than the start of the higher slice, only that single dollar is taxed at the higher rate. Everything underneath is taxed exactly as before."},{"type":"tip","title":"So a raise is still a raise","text":"A higher income-tax bracket alone does not reduce the after-tax income from a raise. Income-tested benefit reductions and other deductions must be considered separately."},{"type":"warning","title":"Rates and thresholds change yearly","text":"This guide deliberately avoids quoting rates or bracket amounts, because federal and provincial numbers are updated annually. Look up the current year on canada.ca."}]'::jsonb, '["Canada taxes income in slices, each at its own rate.","A higher bracket applies only to the dollars in that bracket.","A higher tax bracket alone does not erase the benefit of earning more.","Bracket thresholds and rates change every year — always look them up."]'::jsonb, '[{"label":"Personal income tax — Canada.ca","url":"https://www.canada.ca/en/services/taxes/income-tax/personal-income-tax.html"},{"label":"Canada Revenue Agency","url":"https://www.canada.ca/en/revenue-agency.html"}]'::jsonb, '2026-09-20', true, null, null, 15, 5, false, true)
insert into public.content_quizzes (id, slug, title, description, emoji, kind, category_id, question_ids, featured_from, xp_per_correct, sort_order, published) values
  ('quiz-module-5', 'decoding-your-pay-stub-quiz', 'Decoding Your Pay Stub', 'Module 5 · Five questions with explanations. Read the lesson, then test your understanding.', 'school-outline', 'topic', 'your-paycheque', '["q-module-5-1","q-module-5-2","q-module-5-3","q-module-5-4","q-module-5-5"]'::jsonb, null, 4, 25, true),
  ('quiz-module-6', 'how-tax-brackets-really-work-quiz', 'How Tax Brackets Really Work', 'Module 6 · Five questions with explanations. Read the lesson, then test your understanding.', 'school-outline', 'topic', 'tax-basics', '["q-module-6-1","q-module-6-2","q-module-6-3","q-module-6-4","q-module-6-5"]'::jsonb, null, 4, 26, true),
  ('quiz-module-7', 'side-hustles-and-gig-income-quiz', 'Side Hustles and Gig Income', 'Module 7 · Five questions with explanations. Read the lesson, then test your understanding.', 'school-outline', 'topic', 'employment-and-gig-income', '["q-module-7-1","q-module-7-2","q-module-7-3","q-module-7-4","q-module-7-5"]'::jsonb, null, 4, 27, true),
  ('quiz-module-8', 'free-money-from-filing-quiz', 'Free Money from Filing', 'Module 8 · Five questions with explanations. Read the lesson, then test your understanding.', 'school-outline', 'topic', 'credits-and-benefits', '["q-module-8-1","q-module-8-2","q-module-8-3","q-module-8-4","q-module-8-5"]'::jsonb, null, 4, 28, true),
  ('quiz-module-9', 'fhsa-rrsp-and-big-goals-quiz', 'FHSA, RRSP and Big Goals', 'Module 9 · Five questions with explanations. Read the lesson, then test your understanding.', 'school-outline', 'topic', 'tfsa-and-rrsp', '["q-module-9-1","q-module-9-2","q-module-9-3","q-module-9-4","q-module-9-5"]'::jsonb, null, 4, 29, true),
  ('quiz-module-10', 'moving-out-for-school-quiz', 'Moving Out for School', 'Module 10 · Five questions with explanations. Read the lesson, then test your understanding.', 'school-outline', 'topic', 'slips-and-documents', '["q-module-10-1","q-module-10-2","q-module-10-3","q-module-10-4","q-module-10-5"]'::jsonb, null, 4, 30, true),
  ('quiz-module-11', 'cra-scams-deadlines-and-mistakes-quiz', 'CRA Scams, Deadlines and Mistakes', 'Module 11 · Five questions with explanations. Read the lesson, then test your understanding.', 'school-outline', 'topic', 'deadlines-and-penalties', '["q-module-11-1","q-module-11-2","q-module-11-3","q-module-11-4","q-module-11-5"]'::jsonb, null, 4, 31, true),
  ('quiz-myth-busters', 'myth-busters', 'Myth Busters', 'Ten true-or-false tax myths. Find the catch, then learn why.', 'bulb-outline', 'topic', null, '["q-myth-1","q-myth-2","q-myth-3","q-myth-4","q-myth-5","q-myth-6","q-myth-7","q-myth-8","q-myth-9","q-myth-10"]'::jsonb, null, 4, 32, true),
  ('quiz-benefits', 'credits-and-benefits', 'Credits & Benefits', 'CGEB (formerly GST/HST credit), free help, and payments.', '🎁', 'topic', 'credits-and-benefits', null, null, 4, 5, true)
insert into public.content_questions (id, category_id, prompt, options, answer_index, explanation, teaches_lesson_id, difficulty, published) values
  ('q-module-5-1', 'your-paycheque', 'You worked 20 hours at $17.85. Your stub shows gross pay of $357 and a deposit of $331. What is your net pay?', '["$357","$331","$26"]'::jsonb, 1, 'Net pay is $331. The $26 difference is deductions; read the stub to identify which deductions apply.', 'lesson-module-5', 'easy', true),
  ('q-module-5-2', 'your-paycheque', 'You are 16 with a part-time job. Which deduction should NOT appear on your stub?', '["EI","Income tax","CPP"]'::jsonb, 2, 'CPP generally starts the month after age 18. Ask payroll to correct mistaken deductions; any remaining overpayment can be reconciled when filing.', 'lesson-module-5', 'medium', true),
  ('q-module-5-3', 'your-paycheque', 'True or false: EI is only deducted once you earn over $3,500 a year.', '["True","False"]'::jsonb, 1, 'That $3,500 exemption is for CPP. EI comes off from the first dollar you earn.', 'lesson-module-5', 'medium', true),
  ('q-module-5-4', 'your-paycheque', 'What is the TD1 form for?', '["Filing your tax return","Telling your employer how much tax to withhold","Applying for EI"]'::jsonb, 1, 'It sets your withholding. Most students just claim the basic personal amount.', 'lesson-module-5', 'medium', true),
  ('q-module-5-5', 'your-paycheque', 'Jordan has two jobs at the same time, total income exceeds his basic personal amount, and he claims that amount on both TD1 forms. What risk does this create?', '["A bigger refund","He owes money","Nothing changes"]'::jsonb, 1, 'Both employers may withhold too little tax. A balance may be owing; the final result depends on total income, deductions and credits.', 'lesson-module-5', 'hard', true),
  ('q-module-6-1', 'tax-basics', 'True or false: if your income crosses into a higher bracket, all your income is taxed at the higher rate.', '["True","False"]'::jsonb, 1, 'Only the dollars above the line get the higher rate.', 'lesson-module-6', 'easy', true),
  ('q-module-6-2', 'tax-basics', 'Which rate tells you how much tax you will pay on one extra hour of work?', '["Average rate","Marginal rate","Basic rate"]'::jsonb, 1, 'The marginal rate applies to your next dollar earned.', 'lesson-module-6', 'medium', true),
  ('q-module-6-3', 'tax-basics', 'For a full-year Canadian resident entitled to the maximum 2026 federal basic personal amount, about how much taxable income can that credit offset?', '["$5,000","$16,452","$58,523"]'::jsonb, 1, 'The maximum 2026 federal basic personal amount is $16,452. This is a non-refundable federal credit, not an exemption from payroll deductions or provincial tax; special and high-income rules apply.', 'lesson-module-6', 'medium', true),
  ('q-module-6-4', 'tax-basics', 'In a simple 2026 federal bracket calculation, some income is taxed at 14% and the next dollar at 20.5%. Compared with 20.5%, is the average rate higher, lower or the same?', '["Higher","Always exactly the same","Lower in this simple bracket example"]'::jsonb, 2, 'Lower: part of the income is taxed in the lower bracket. Credits can reduce the effective rate further.', 'lesson-module-6', 'medium', true),
  ('q-module-6-5', 'tax-basics', 'Assuming identical total taxable income, deductions and credits, who owes more final federal income tax: one $60,000 job or two $30,000 jobs?', '["The person with one job","The same, with identical deductions and credits","The person with two jobs"]'::jsonb, 1, 'The final federal income tax is the same under those assumptions. Payroll withholding may differ.', 'lesson-module-6', 'hard', true),
  ('q-module-7-1', 'employment-and-gig-income', 'True or false: tips from a restaurant job are tax-free.', '["True","False"]'::jsonb, 1, 'Tips are income and must be reported, whether cash or card.', 'lesson-module-7', 'easy', true),
  ('q-module-7-2', 'employment-and-gig-income', 'Your jewelry business has $4,000 of revenue and $1,000 of eligible material expenses. What is the net profit?', '["$4,000","$3,000","$0, it is a hobby"]'::jsonb, 1, 'Net profit is $3,000. On the business statement, report both the $4,000 gross revenue and the $1,000 eligible expenses.', 'lesson-module-7', 'medium', true),
  ('q-module-7-3', 'employment-and-gig-income', 'A brand sends you a free $300 hoodie in exchange for a TikTok post. Is that taxable?', '["No, because no cash changed hands","Only if the hoodie is sold later","Yes, its fair market value is business income"]'::jsonb, 2, 'Yes. Products received in exchange for promotion count as income at their fair value.', 'lesson-module-7', 'medium', true),
  ('q-module-7-4', 'employment-and-gig-income', 'You sell your own old clothes on Vinted for less than you paid. Do you owe tax?', '["Only if payment is by e-transfer","Generally no taxable gain on ordinary used clothes sold at a loss","Yes, tax is due on every personal sale"]'::jsonb, 1, 'No. Selling personal items at a loss is not income. Buying items to resell for profit is a business.', 'lesson-module-7', 'medium', true),
  ('q-module-7-5', 'employment-and-gig-income', 'A self-employed 20-year-old nets $15,000. Why is her CPP higher than a regular employee''s on the same income?', '["She pays both employee and employer CPP shares","She pays a special under-25 tax","Her clients pay her CPP automatically"]'::jsonb, 0, 'She pays both the employee and employer shares of CPP, since she is her own boss.', 'lesson-module-7', 'hard', true),
  ('q-module-8-1', 'credits-and-benefits', 'True or false: if you earned under the basic personal amount, there is no reason to file.', '["True","False"]'::jsonb, 1, 'Filing can get back withheld tax and unlock benefits like the GST/HST credit.', 'lesson-module-8', 'easy', true),
  ('q-module-8-2', 'credits-and-benefits', 'Your only insurable earnings for the year were $1,800 at a daycare and EI was deducted. What happens when you file?', '["The EI premiums are never refundable","Only half is refunded","The EI premiums are refunded if total insurable earnings were $2,000 or less"]'::jsonb, 2, 'Your EI premiums come back, since your insurable earnings were $2,000 or less.', 'lesson-module-8', 'medium', true),
  ('q-module-8-3', 'credits-and-benefits', 'At what age does CGEB eligibility generally begin for a Canadian resident who has no spouse or common-law partner and is not a parent living with their child?', '["16","18","19"]'::jsonb, 2, 'Generally 19. File the year before you turn 19 so the CRA can assess eligibility. CGEB replaced the GST/HST credit in July 2026; eligibility and income tests still apply.', 'lesson-module-8', 'medium', true),
  ('q-module-8-4', 'credits-and-benefits', 'Is the Canada Groceries and Essentials Benefit (formerly GST/HST credit) taxable income?', '["No, it is a tax-free benefit","Yes, it is employment income","Only if it is paid quarterly"]'::jsonb, 0, 'No. It is a tax-free benefit, not taxable income.', 'lesson-module-8', 'medium', true),
  ('q-module-8-5', 'credits-and-benefits', 'Priya is 17 and CPP was deducted by mistake. If payroll has not reimbursed the overpayment, how can it be reconciled?', '["Ask her employer for cash","File a tax return","She cannot"]'::jsonb, 1, 'File a tax return to reconcile any remaining CPP overpayment. Asking payroll to correct the deduction is also appropriate.', 'lesson-module-8', 'hard', true),
  ('q-module-9-1', 'tfsa-and-rrsp', 'What does FHSA stand for?', '["Federal Housing Support Allowance","Flexible Home Spending Account","First Home Savings Account"]'::jsonb, 2, 'First Home Savings Account.', 'lesson-module-9', 'easy', true),
  ('q-module-9-2', 'tfsa-and-rrsp', 'You earned $10,000 last year. Ignoring pension adjustments and other adjustments, how much new RRSP room does the 18% rule produce?', '["$1,000","$1,800","$7,000"]'::jsonb, 1, '18% of $10,000 is $1,800. Annual limits and pension adjustments can affect actual room; verify the amount with CRA.', 'lesson-module-9', 'medium', true),
  ('q-module-9-3', 'tfsa-and-rrsp', 'True or false: you build FHSA room every year from age 18, even if you never open one.', '["True","False"]'::jsonb, 1, 'FHSA room starts in the year you open your first FHSA, not automatically at 18. Opening also starts the maximum participation period; check eligibility and timing before opening.', 'lesson-module-9', 'medium', true),
  ('q-module-9-4', 'tfsa-and-rrsp', 'You opened an FHSA last year but put nothing in. What is the most you can contribute this year?', '["$8,000","$40,000","$16,000, assuming no contributions or transfers and no other adjustments"]'::jsonb, 2, '$16,000. Up to $8,000 of unused room carries forward, on top of this year''s $8,000.', 'lesson-module-9', 'hard', true),
  ('q-module-9-5', 'tfsa-and-rrsp', 'You live in BC and just turned 18. Can you open a TFSA?', '["Not until age 21","Not yet: BC generally requires age 19 to open it","Yes: every province allows opening at 18"]'::jsonb, 1, 'In BC, the legal age to open a TFSA is generally 19. Eligible Canadian residents begin accumulating TFSA contribution room at 18.', 'lesson-module-9', 'hard', true),
  ('q-module-10-1', 'slips-and-documents', 'Which slip shows the tuition you paid for the year?', '["T4","T2202","T5"]'::jsonb, 1, 'Your school posts the T2202, usually in your student portal.', 'lesson-module-10', 'easy', true),
  ('q-module-10-2', 'slips-and-documents', 'True or false: unused tuition credits disappear if you do not use them that year.', '["True","False"]'::jsonb, 1, 'They carry forward with no expiry, so you can use them once you are earning more.', 'lesson-module-10', 'medium', true),
  ('q-module-10-3', 'slips-and-documents', 'You received a $3,000 entrance scholarship connected to a qualifying full-time post-secondary program. How should you handle it?', '["Include the full $3,000 as taxable income automatically","Treat it as employment income","Enter the slip and apply the scholarship exemption; only a taxable portion goes on line 13010"]'::jsonb, 2, 'Apply the scholarship exemption correctly. A fully exempt scholarship is not reported as taxable income on line 13010; tax software may ask you to enter the T4A first.', 'lesson-module-10', 'medium', true),
  ('q-module-10-4', 'slips-and-documents', 'You move from Kelowna to Vancouver for full-time university. When could moving expenses be deductible?', '["Never, because students cannot deduct moving expenses","Only if the qualifying move and eligible-income rules are met","Always, because any university move qualifies"]'::jsonb, 1, 'The new home must generally be at least 40 km closer to the qualifying school or new work location. A student move is limited to eligible taxable scholarship or similar income; a qualifying work move has its own rules. Simply taking a nearby job does not automatically qualify the move.', 'lesson-module-10', 'hard', true),
  ('q-module-10-5', 'slips-and-documents', 'Your parents'' RESP pays you $6,000, made up of $4,000 they contributed and $2,000 of growth and grants. How much counts as your income?', '["$2,000 of growth and grants","$6,000","$4,000 of original contributions"]'::jsonb, 0, '$2,000. Your parents'' own contributions come back tax-free. Only the growth and grants are taxed in your hands.', 'lesson-module-10', 'hard', true),
  ('q-module-11-1', 'deadlines-and-penalties', 'A caller says you owe the CRA $1,200 and must pay in Apple gift cards today or be arrested. What is this?', '["A scam: hang up and check through official CRA channels","A valid CRA payment request","A legitimate discount offer"]'::jsonb, 0, 'A scam. Hang up and check your balance yourself in CRA My Account.', 'lesson-module-11', 'easy', true),
  ('q-module-11-2', 'deadlines-and-penalties', 'True or false: the standard individual late-filing penalty for a balance owing does not apply when your return instead results in a refund.', '["True","False"]'::jsonb, 0, 'True for that penalty. File promptly anyway: refunds and benefits can be delayed, and other reporting obligations can carry separate penalties.', 'lesson-module-11', 'medium', true),
  ('q-module-11-3', 'deadlines-and-penalties', 'Under the standard first-time late-filing rule, you owe $500 and file three full months late. What is the penalty before interest?', '["$25","$40","$65"]'::jsonb, 1, '5% of $500 is $25, plus $15 for three full months: $40. Interest is separate; repeat late-filing rules can be higher.', 'lesson-module-11', 'medium', true),
  ('q-module-11-4', 'deadlines-and-penalties', 'A self-employed creator files on June 10 and pays her $800 balance that day. Did she do anything wrong?', '["She filed on time but may owe late-payment interest","Both filing and payment were on time","She must file a duplicate return"]'::jsonb, 0, 'Partly. Filing by June 15 is on time, but payment was due April 30, so she owes interest on the $800.', 'lesson-module-11', 'hard', true),
  ('q-module-11-5', 'deadlines-and-penalties', 'After receiving your Notice of Assessment, you spot a mistake on your return. What should you do?', '["File a second return","Request a change in My Account","Wait for the CRA to notice"]'::jsonb, 1, 'Request an adjustment using Change my return, eligible ReFILE software, or Form T1-ADJ. Wait for the assessment and do not submit a duplicate return.', 'lesson-module-11', 'hard', true),
  ('q-myth-1', 'tax-basics', 'Lottery winnings are generally taxable income for a casual lottery player in Canada.', '["True","False"]'::jsonb, 1, 'Lottery winnings are generally not taxable. Income later earned by investing the winnings can be taxable.', 'lesson-module-6', 'medium', true),
  ('q-myth-2', 'tax-basics', 'A personal $500 birthday cash gift from your parents counts as taxable income.', '["True","False"]'::jsonb, 1, 'A genuine personal cash gift is generally not taxable to the recipient. Payment for work is different.', 'lesson-module-6', 'medium', true),
  ('q-myth-3', 'credits-and-benefits', 'A large tax refund is automatically a bonus from the government.', '["True","False"]'::jsonb, 1, 'A refund may reflect overpaid tax and/or refundable credits. It is not an automatic bonus; look at the assessment to see why it arose.', 'lesson-module-8', 'medium', true),
  ('q-myth-4', 'first-tax-return', 'You must be 18 to file an income tax return.', '["True","False"]'::jsonb, 1, 'There is no minimum filing age. Reporting earned income can establish future RRSP room.', 'lesson-module-8', 'medium', true),
  ('q-myth-5', 'first-tax-return', 'You must pay a professional to prepare every tax return.', '["True","False"]'::jsonb, 1, 'Free certified software exists, and eligible people with modest income and a simple tax situation can use volunteer clinics.', 'lesson-module-8', 'medium', true),
  ('q-myth-6', 'tfsa-and-rrsp', 'A TFSA withdrawal permanently removes that amount from your contribution room.', '["True","False"]'::jsonb, 1, 'Withdrawals are generally added back on January 1 of the following calendar year. Replacing them earlier without other room can cause an overcontribution.', 'lesson-module-9', 'medium', true),
  ('q-myth-7', 'saving-and-investing', 'Interest from an ordinary non-registered savings account is tax-free.', '["True","False"]'::jsonb, 1, 'Interest is generally taxable even if no T5 is issued. Registered accounts have distinct rules; TFSA and FHSA are not the only tax-advantaged plans.', 'lesson-module-9', 'medium', true),
  ('q-myth-8', 'saving-and-investing', 'Crypto can trigger tax only when it is exchanged for dollars.', '["True","False"]'::jsonb, 1, 'Exchanging one crypto-asset for another is also a disposition that can create a gain or loss. Business-income or capital-gain rules depend on the facts.', 'lesson-module-7', 'medium', true),
  ('q-myth-9', 'employment-and-gig-income', 'A Canadian tax resident can ignore YouTube business revenue paid in US dollars.', '["True","False"]'::jsonb, 1, 'Canadian tax residents generally report worldwide income. Convert foreign-currency amounts into Canadian dollars using an appropriate exchange rate.', 'lesson-module-7', 'medium', true),
  ('q-myth-10', 'slips-and-documents', 'If your employer has not sent a T4, you have no employment income to report.', '["True","False"]'::jsonb, 1, 'Ask for the missing slip and check CRA My Account. If necessary, use records to estimate the income and deductions and correct the return when accurate information arrives.', 'lesson-module-11', 'medium', true),
  ('q-ben-1', 'credits-and-benefits', 'To qualify for the CGEB (formerly GST/HST credit) on your own, you generally must be at least…', '["16","18","19","25"]'::jsonb, 2, 'You generally need to be 19 or older to get the CGEB (formerly GST/HST credit) on your own (younger people can qualify if they are a parent or have a spouse/partner).', 'lesson-credits-benefits', null, true),
  ('q-ben-2', 'credits-and-benefits', 'How do you receive the CGEB (formerly GST/HST credit) and related benefits?', '["Apply at a bank","By filing your tax return — it''s assessed automatically","Call your employer","You can''t get it under 30"]'::jsonb, 1, 'Just file your return. The CRA works out your eligibility automatically from it.', 'lesson-credits-benefits', null, true),
  ('q-ben-3', 'credits-and-benefits', 'Is the CGEB (formerly GST/HST credit) considered taxable income?', '["Yes, you pay tax on it","No — it''s tax-free","Only half of it","Only if you''re employed"]'::jsonb, 1, 'The CGEB (formerly GST/HST credit) is a tax-free payment meant to offset sales tax for lower-income people.', 'lesson-credits-benefits', null, true),
  ('q-ben-4', 'credits-and-benefits', 'Filing your taxes matters mainly because…', '["It''s fun","Your benefit and credit payments are calculated from your return","It raises your credit score","It cancels your student loans"]'::jsonb, 1, 'Payments like the CGEB (formerly GST/HST credit) and Canada Child Benefit are based on the info in your return — no return, no payments.', 'lesson-credits-benefits', null, true)
insert into public.content_glossary (term, definition, category_id) values
  ('CGEB (formerly GST/HST credit)', 'A tax free payment that helps lower income people with sales tax.', 'credits-and-benefits')
insert into public.content_faqs (id, question, answer, sort_order, published) values
  ('faq-canadian', 'Is the tax info Canadian or American?', 'Canadian. Our content is based on the Canada Revenue Agency (CRA) and Canadian rules — things like T4s, TFSAs, RRSPs, and the CGEB (formerly GST/HST credit).', 7, true)
