-- Add October 2026 curriculum without resetting unrelated content or learner progress.

alter table public.content_questions add column if not exists difficulty text check (difficulty in ('easy', 'medium', 'hard'));

update public.content_glossary set term = 'CGEB (formerly GST/HST credit)' where term = 'GST/HST credit' and not exists (select 1 from public.content_glossary where term = 'CGEB (formerly GST/HST credit)');

on conflict (id) do update set slug = excluded.slug, title = excluded.title, category_id = excluded.category_id, kind = excluded.kind, summary = excluded.summary, reading_minutes = excluded.reading_minutes, body = excluded.body, key_takeaways = excluded.key_takeaways, official_sources = excluded.official_sources, last_reviewed = excluded.last_reviewed, needs_verification = excluded.needs_verification, related_video_id = excluded.related_video_id, related_quiz_id = excluded.related_quiz_id, xp = excluded.xp, sort_order = excluded.sort_order, featured = excluded.featured, published = excluded.published;

on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, emoji = excluded.emoji, kind = excluded.kind, category_id = excluded.category_id, question_ids = excluded.question_ids, featured_from = excluded.featured_from, xp_per_correct = excluded.xp_per_correct, sort_order = excluded.sort_order, published = excluded.published;

on conflict (id) do update set category_id = excluded.category_id, prompt = excluded.prompt, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, teaches_lesson_id = excluded.teaches_lesson_id, difficulty = excluded.difficulty, published = excluded.published;

on conflict (term) do update set definition = excluded.definition, category_id = excluded.category_id;

on conflict (id) do update set question = excluded.question, answer = excluded.answer, sort_order = excluded.sort_order, published = excluded.published;

update public.content_lessons set related_quiz_id = 'quiz-module-5', related_video_id = null where id = 'lesson-module-5';

